commands.command:
cat <<'ANTRIEB_EOF' | sudo -n tee /etc/nginx/sites-available/cert-rotation.conf > /dev/null
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name _;

    ssl_certificate     /etc/nginx/certs/cert.pem;
    ssl_certificate_key /etc/nginx/certs/key.pem;

    location / {
        return 200 "cert-rotation-ok\n";
        add_header Content-Type text/plain;
    }
}
ANTRIEB_EOF
sudo -n ln -sf /etc/nginx/sites-available/cert-rotation.conf /etc/nginx/sites-enabled/cert-rotation.conf
sudo -n nginx -t
sudo -n systemctl reload nginx
ss -tlnp 2>&1 | grep 8443
